From: Drew DeVault <sir@cmpwn.com>
Date: Tue, 2 May 2017 20:46:27 -0400
Subject: [PATCH] Do not zero RGB pixels if A == 0 (#43)

This fixes a problem introduced by
5ed200d5d73edc54969b34c708d18728d38c070b.

diff --git a/src/pngcodec.c b/src/pngcodec.c
index bac40b1..c51188d 100644
--- a/src/pngcodec.c
+++ b/src/pngcodec.c
@@ -455,16 +455,12 @@ gdip_load_png_image_from_file_or_stream (FILE *fp, GetBytesDelegate getBytesFunc
 				for (i = 0; i < height; i++) {
 					png_bytep rowp = row_pointers[i];
 					for (j = 0; j < width; j++) {
+						BYTE b = rowp[2];
+						BYTE g = rowp[1];
+						BYTE r = rowp[0];
 						BYTE a = rowp[3];
-						if (a == 0) {
-							set_pixel_bgra (rawptr, 0, 0, 0, 0, 0);
-						} else {
-							BYTE b = rowp[2];
-							BYTE g = rowp[1];
-							BYTE r = rowp[0];
-
-							set_pixel_bgra (rawptr, 0, b, g, r, a);
-						}
+
+						set_pixel_bgra (rawptr, 0, b, g, r, a);
 						rowp += 4;
 						rawptr += 4;
 					}
